# Load the grids from this session
import os, glob, re

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows_raw = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows_raw):
            G[k] = [[int(x) for x in r] for r in rows_raw]
    return G

G = load()
for k, v in sorted(G.items()):
    print(f"{k} {len(v)}x{len(v[0])}:")
    for row in v:
        print(' '.join(str(x) for x in row))
