]

h, w = 7, 22
bg = 9
marker_val = 1
special_val = 3

print("Approach 1: Global bbox of special values only")
special_only_points = []
for r in range(h):
    for c in range(w):
        if test_input[r][c] == special_val:
            special_only_points.append((r,c))

if special_only_points:
    sr, sc = min(p[0] for p in special_only_points), min(p[1] for p in special_only_points)
    smax_r, smax_c = max(p[0] for p in special_only_points), max(p[1] for p in special_only_points)
    print(f"Special bbox: rows [{sr}-{smax_r}], cols [{sc}-{smax_c}]")

    result = [[bg]*w for _ in range(h)]

    # Fill the special bounding box
    for r in range(sr, smax_r+1):
        for c in range(sc, smax_c+1):
            val = test_input[r][c]
            if val == bg:
                result[r][c] = 1
            elif val == special_val:
                result[r][c] = 4

    print("\nOutput (special-bbox fill):")
    for row in result:
        print(' '.join(str(x) for x in row))
else:
    print("No special values!")

print("\n\n=== Approach 2: Per-row edge markers ===")
result2 = [[bg]*w for _ in range(h)]

