# Row 6 has marker at left edge

# Rule: Edge marker triggers fill AWAY from edge toward center
if test_input[0][w-1] == marker_val:
    # Fill row 0 LEFTWARD from col 21
    for c in range(0, w-1):
        orig = test_input[0][c]
        if orig == bg:
            result2[0][c] = 1
        elif orig == special_val:
            result2[0][c] = 4

if test_input[6][0] == marker_val:
    # Fill row 6 RIGHTWARD from col 0  
    for c in range(1, w):
        orig = test_input[6][c]
        if orig == bg:
            result2[6][c] = 1
        elif orig == special_val:
            result2[6][c] = 4

print("\nRow-by-row:")
for r in range(h):
    out = result2[r]
    desc = "edge" if (r==0 and out[w-2]==1) or (r==6 and out[1]==1) else "no_change"
    print(f"Row {r}: {''.join(str(x).center(2) for x in out)} [{desc}]")

